<script setup lang="ts">
import { formatDateTime } from "../../../../../../utils/format";
definePageMeta({ middleware: "project-exists" });
const route = useRoute(); const router = useRouter();
const projectId = computed(() => String(route.params.projectId)); const scheduleId = computed(() => String(route.params.scheduleId)); const executionId = computed(() => String(route.params.executionId));
const api = useTestScheduleExecutions(projectId, scheduleId); const detail = shallowRef<TestScheduleExecutionDetail | null>(null); const loading = ref(true);
const deliveryApi = useNotificationDeliveries(executionId); const retryingId = ref<string | null>(null);
onMounted(async () => { detail.value = await api.get(executionId.value); loading.value = false; });
async function retryDelivery(deliveryId: string): Promise<void> { retryingId.value = deliveryId; const result = await deliveryApi.retryNotificationDelivery(deliveryId); retryingId.value = null; if (result) detail.value = await api.get(executionId.value); }
</script>
<template><div><AppPageHeader title="예약 실행 상세" description="실행 당시 일정 스냅샷과 채널별 전달 결과입니다."><el-button @click="router.push(`/projects/${projectId}/schedules/${scheduleId}`)">예약으로 돌아가기</el-button></AppPageHeader><div v-if="loading" class="form-panel"><el-skeleton :rows="8" animated /></div><el-alert v-else-if="!detail" :title="api.error.value ?? '실행을 찾을 수 없습니다.'" type="error" show-icon /><template v-else><section class="info-strip"><div><span>상태</span><strong><AppStatusBadge :status="detail.execution.status" /></strong></div><div><span>예정</span><strong>{{ formatDateTime(detail.execution.scheduledFor) }}</strong></div><div><span>시작</span><strong>{{ formatDateTime(detail.execution.startedAt) }}</strong></div><div><span>회귀</span><strong>{{ detail.execution.regressionCount }}건</strong></div></section><el-alert v-if="detail.execution.errorMessage || detail.execution.skipReason" :title="detail.execution.errorMessage ?? detail.execution.skipReason" type="warning" show-icon class="page-alert" /><section class="content-section"><div class="section-heading"><div><h2>일정 스냅샷</h2><p>{{ detail.execution.scheduleSnapshot.scheduleName }} · {{ detail.execution.scheduleSnapshot.suiteName }}</p></div></div><pre class="json-preview">{{ JSON.stringify(detail.execution.scheduleSnapshot, null, 2) }}</pre></section><section class="content-section"><div class="section-heading"><div><h2>알림 전달</h2><p>채널과 수신자는 마스킹된 형태로만 표시됩니다.</p></div></div><AppEmptyState v-if="!detail.deliveries.length" title="전달 기록이 없습니다" description="알림 조건에 해당하지 않았거나 알림이 비활성 상태입니다." /><el-table v-else :data="detail.deliveries"><el-table-column prop="channel" label="채널" width="120" /><el-table-column prop="recipientMasked" label="수신 대상" min-width="180" /><el-table-column label="상태" width="130"><template #default="scope"><AppStatusBadge :status="scope.row.status" /></template></el-table-column><el-table-column prop="attemptCount" label="시도" width="80" /><el-table-column prop="errorMessage" label="오류" min-width="200" /><el-table-column label="작업" width="110"><template #default="scope"><el-button v-if="scope.row.status === 'failed' && scope.row.retryable !== false" text type="primary" :loading="retryingId === scope.row.id" @click="retryDelivery(scope.row.id)">재전송</el-button></template></el-table-column></el-table></section></template></div></template>
